(r, big) => {
    const nd = v => ({ v, L: null, R: null });
    const V = () => r.int(0, big ? 200 : 2);
    const put = (t, x) => { if (!t) return x; let c = t; for (;;) { const k = r.bool() ? "L" : "R"; if (!c[k]) { c[k] = x; return t; } c = c[k]; } };
    const rnd = n => { let t = null; for (let i = 0; i < n; i++) t = put(t, nd(V())); return t; };
    const leaves = (t, out) => { if (!t.L && !t.R) out.push(t.v); else { if (t.L) leaves(t.L, out); if (t.R) leaves(t.R, out); } return out; };
    // build a tree whose leaves are exactly seq, in order
    const fromLeaves = seq => {
      if (seq.length === 1) { const t = nd(V()); t.v = seq[0]; return r.bool(0.3) ? Object.assign(nd(V()), r.bool() ? { L: t } : { R: t }) : t; }
      const cut = r.int(1, seq.length - 1), t = nd(V());
      t.L = fromLeaves(seq.slice(0, cut)); t.R = fromLeaves(seq.slice(cut));
      return t;
    };
    const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
    const n = big ? 200 : r.int(1, 7);
    const a = rnd(n);
    let b;
    const seq = leaves(a, []);
    if (r.bool(0.5) && seq.length * 3 <= (big ? 200 : 14)) {
      const s = seq.slice();
      if (r.bool(0.3)) { const i = r.int(0, s.length - 1); s[i] = (s[i] + 1) % 3; }
      b = fromLeaves(s);
    } else b = rnd(big ? 200 : r.int(1, 7));
    return [ser(a), ser(b)];
  }

