function sameLeafSequence(a: TreeNode | null, b: TreeNode | null): boolean {
  const collect = (t: TreeNode | null, out: number[]): number[] => {
    if (!t) return out;
    if (!t.left && !t.right) out.push(t.val);
    collect(t.left, out);
    collect(t.right, out);
    return out;
  };
  const x = collect(a, []), y = collect(b, []);
  return x.length === y.length && x.every((v, i) => v === y[i]);
}

