function sameLeafSequence(a: TreeNode | null, b: TreeNode | null): boolean {
  // returns the next leaf value, or null when the tree is exhausted
  const nextLeaf = (stack: TreeNode[]): number | null => {
    while (stack.length) {
      const t = stack.pop()!;
      if (!t.left && !t.right) return t.val;
      if (t.right) stack.push(t.right);
      if (t.left) stack.push(t.left);
    }
    return null;
  };
  const sa: TreeNode[] = a ? [a] : [], sb: TreeNode[] = b ? [b] : [];
  for (;;) {
    const x = nextLeaf(sa), y = nextLeaf(sb);
    if (x !== y) return false;
    if (x === null) return true;
  }
}

